// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily } = loadFont();

// Data points representing the classic "hockey stick" growth curve
const CHART_DATA = [
  0.03, 0.04, 0.05, 0.04, 0.06, 0.07, 0.06, 0.08, 0.11, 0.09, 
  0.14, 0.15, 0.12, 0.11, 0.09, 0.10, 0.11, 0.08, 0.06, 0.05, 
  0.04, 0.03, 0.04, 0.03, 0.05, 0.04, 0.02, 0.03, 0.05, 0.06, 
  0.08, 0.09, 0.11, 0.10, 0.09, 0.12, 0.15, 0.18, 0.16, 0.17, 
  0.15, 0.14, 0.13, 0.17, 0.16, 0.15, 0.18, 0.20, 0.28, 0.35, 
  0.38, 0.32, 0.40, 0.42, 0.45, 0.48, 0.46, 0.50, 0.44, 0.40, 
  0.45, 0.48, 0.47, 0.46, 0.41, 0.38, 0.32, 0.25, 0.35, 0.40, 
  0.45, 0.55, 0.60, 0.62, 0.58, 0.65, 0.70, 0.65, 0.75, 0.72, 
  0.68, 0.73, 0.70, 0.74, 0.68, 0.75, 0.85, 0.80, 0.82, 0.75, 
  0.71, 0.80, 0.88, 0.95, 0.90, 0.92, 0.98, 1.00
];



export type StockChartProps = Record<string, any>;

const StockChart: React.FC<StockChartProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 6,
  ticker = "NVIDIA",
  tickerColor = "#ffffff",
  startPrice = 14.79,
  targetPrice = 231.11,
  priceColor = "#ffffff",
  gainColor = "#12D939",
  lossColor = "#FF3333",
  timeframe = "Past 5 years",
  timeframeColor = "#ffffff",
  lineColorGain = "#12D939",
  lineColorLoss = "#FF3333",
  lineWidth = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Determine trend
  const isGainTotal = targetPrice >= startPrice;
  const activeLineColor = isGainTotal ? lineColorGain : lineColorLoss;
  const activeChangeColor = isGainTotal ? gainColor : lossColor;

  // Layout Calculations
  const paddingX = width * 0.08;
  const paddingTop = height * 0.12;
  const chartWidth = width - (paddingX * 2);
  const chartHeight = height * 0.45;

  // Generate SVG Path purely and deterministically
  const rawPath = useMemo(() => {
    let pathString = "";
    const usableWidth = chartWidth - lineWidth;
    const usableHeight = chartHeight - lineWidth;
    const offsetX = lineWidth / 2;
    const offsetY = lineWidth / 2;

    CHART_DATA.forEach((val, i) => {
      const x = offsetX + (i / (CHART_DATA.length - 1)) * usableWidth;
      
      // If it's a loss, invert the data curve so it trends downwards visually
      const finalVal = isGainTotal ? val : (1 - val);
      const y = offsetY + (usableHeight - (finalVal * usableHeight));
      
      if (i === 0) pathString += `M ${x} ${y} `;
      else pathString += `L ${x} ${y} `;
    });
    return pathString;
  }, [chartWidth, chartHeight, lineWidth, isGainTotal]);

  // Animation Timings
  const text1Progress = spring({ frame, fps, config: { damping: 15 } });
  const text2Progress = spring({ frame: Math.max(0, frame - 10), fps, config: { damping: 15 } });
  const text3Progress = spring({ frame: Math.max(0, frame - 20), fps, config: { damping: 15 } });

  const chartStartFrame = 25;
  const chartDurationFrames = fps * 3.5; // Draw over 3.5 seconds
  
  const pathProgress = interpolate(
    frame,
    [chartStartFrame, chartStartFrame + chartDurationFrames],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Dynamic values
  const currentPrice = interpolate(
    pathProgress,
    [0, 1],
    [startPrice, targetPrice]
  );
  
  const displayPrice = `$${currentPrice.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;

  const isCurrentGain = currentPrice >= startPrice;
  const currentChangeValue = Math.abs(currentPrice - startPrice);
  const currentChangePercent = startPrice > 0 ? (currentChangeValue / startPrice) * 100 : 0;
  
  const sign = isCurrentGain ? "+" : "-";
  const displayChangeColor = isCurrentGain ? gainColor : lossColor;
  
  const displayChange = `${sign}$${currentChangeValue.toFixed(2)} (${sign}${currentChangePercent.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}%)`;

  // Draw chart based on progress
  const evolution = evolvePath(pathProgress, rawPath);

  // Interpolated Styles
  const y1 = interpolate(text1Progress, [0, 1], [40, 0]);
  const y2 = interpolate(text2Progress, [0, 1], [40, 0]);
  const y3 = interpolate(text3Progress, [0, 1], [40, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily }}>
      
      {/* Text Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          paddingTop: paddingTop,
          paddingLeft: paddingX,
          paddingRight: paddingX,
          gap: "10px",
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: "90px",
            fontWeight: 700,
            color: tickerColor,
            opacity: text1Progress,
            transform: `translateY(${y1}px)`,
            lineHeight: 1.1,
          }}
        >
          {ticker}
        </h1>
        
        <h2
          style={{
            margin: 0,
            fontSize: "140px",
            fontWeight: 700,
            color: priceColor,
            opacity: text2Progress,
            transform: `translateY(${y2}px)`,
            lineHeight: 1.1,
          }}
        >
          {displayPrice}
        </h2>
        
        <div
          style={{
            display: "flex",
            gap: "15px",
            alignItems: "center",
            marginTop: "20px",
            opacity: text3Progress,
            transform: `translateY(${y3}px)`,
            flexWrap: "wrap",
          }}
        >
          <span
            style={{
              color: displayChangeColor,
              fontSize: "45px",
              fontWeight: 600,
              whiteSpace: "nowrap",
            }}
          >
            {displayChange}
          </span>
          <span
            style={{
              color: timeframeColor,
              fontSize: "45px",
              fontWeight: 400,
              opacity: 0.9,
            }}
          >
            {timeframe}
          </span>
        </div>
      </div>

      {/* Chart Container - Fixed to bottom half */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.12, // Respect bottom safe zone
          left: paddingX,
          width: chartWidth,
          height: chartHeight,
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox={`0 0 ${chartWidth} ${chartHeight}`}
          style={{ overflow: "visible" }}
        >
          <path
            d={rawPath}
            fill="none"
            stroke={activeLineColor}
            strokeWidth={lineWidth}
            strokeDasharray={evolution.strokeDasharray}
            strokeDashoffset={evolution.strokeDashoffset}
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ transition: "none" }}
          />
        </svg>
      </div>

    </AbsoluteFill>
  );
};

export default StockChart;